(184312, 10662, 4585, '<td valign="top">Oh well done for the concept.  The image suffers from low tones.  The lighting drowned out the redness of the apple.  Good luck.</td>', 'Oh well done for the concept.  The image suffers from low tones.  The lighting drowned out the redness of the apple.  Good luck.', '2003-01-06 20:52:23.000000', NULL, 1),
(184314, 10686, 4585, '<td valign="top">Soft focus....excellent subject!  GL!</td>', 'Soft focus....excellent subject!  GL!', '2003-01-06 20:53:46.000000', NULL, 1),
(184317, 10627, 4585, '<td valign="top">HAHAHAHAHAHAHAHA!!!!!  Love it....GL!</td>', 'HAHAHAHAHAHAHAHA!!!!!  Love it....GL!', '2003-01-06 20:55:02.000000', NULL, 1),
